PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Alludugaru dbr:The_Laughing_Woman }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?bd1 . }
  OPTIONAL { ?director dbp:birthDate ?bd2 . }
  BIND(coalesce(?bd1, ?bd2) AS ?birthDate)

  VALUES ?film2 { dbr:Alludugaru dbr:The_Laughing_Woman }
  ?film2 dbo:director ?director2 .
  OPTIONAL { ?director2 dbo:birthDate ?bd12 . }
  OPTIONAL { ?director2 dbp:birthDate ?bd22 . }
  BIND(coalesce(?bd12, ?bd22) AS ?birthDate2)

  FILTER(?film != ?film2)
  FILTER(bound(?birthDate) && bound(?birthDate2) && (?birthDate > ?birthDate2))

  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(langMatches(lang(?filmLabel), "EN")) }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(langMatches(lang(?directorLabel), "EN")) }
}

